import{_ as a,o as i,c as t,a1 as s}from"./chunks/framework.DYnGRJP5.js";const u=JSON.parse('{"title":"Setup & Deployment Guide","description":"","frontmatter":{},"headers":[],"relativePath":"verto/setup-and-deployment.md","filePath":"verto/setup-and-deployment.md"}'),n={name:"verto/setup-and-deployment.md"};function o(l,e,r,p,d,c){return i(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="setup-deployment-guide" tabindex="-1">Setup &amp; Deployment Guide <a class="header-anchor" href="#setup-deployment-guide" aria-label="Permalink to &quot;Setup &amp; Deployment Guide&quot;">​</a></h1><p>This guide covers how to set up the external services required for VERTO, configure environment variables, and run the application locally or deploy it.</p><h2 id="_1-prerequisites" tabindex="-1">1. Prerequisites <a class="header-anchor" href="#_1-prerequisites" aria-label="Permalink to &quot;1. Prerequisites&quot;">​</a></h2><p>You need accounts for the following services:</p><ul><li><strong>Firebase</strong> (Authentication &amp; Firestore)</li><li><strong>GitHub</strong> (OAuth application for login &amp; Daily Sync)</li><li><strong>Spotify Developer</strong> (API access for the Audio Engine)</li><li><strong>Node.js</strong> (v18+ recommended)</li></ul><h2 id="_2-environment-variables" tabindex="-1">2. Environment Variables <a class="header-anchor" href="#_2-environment-variables" aria-label="Permalink to &quot;2. Environment Variables&quot;">​</a></h2><p>Create a <code>.env</code> file in the root directory (<code>verto/verto/.env</code>) and populate it with the following keys:</p><div class="language-env vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">env</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># FIREBASE CONFIGURATION</span></span>
<span class="line"><span>VITE_FIREBASE_API_KEY=your_api_key_here</span></span>
<span class="line"><span>VITE_FIREBASE_AUTH_DOMAIN=your_project.firebaseapp.com</span></span>
<span class="line"><span>VITE_FIREBASE_PROJECT_ID=your_project_id</span></span>
<span class="line"><span>VITE_FIREBASE_STORAGE_BUCKET=your_bucket</span></span>
<span class="line"><span>VITE_FIREBASE_MESSAGING_SENDER_ID=your_sender_id</span></span>
<span class="line"><span>VITE_FIREBASE_APP_ID=your_app_id</span></span>
<span class="line"><span></span></span>
<span class="line"><span># SPOTIFY CONFIGURATION</span></span>
<span class="line"><span>VITE_SPOTIFY_CLIENT_ID=your_spotify_client_id_here</span></span></code></pre></div><hr><h2 id="_3-external-service-configuration" tabindex="-1">3. External Service Configuration <a class="header-anchor" href="#_3-external-service-configuration" aria-label="Permalink to &quot;3. External Service Configuration&quot;">​</a></h2><h3 id="a-firebase-setup" tabindex="-1">A. Firebase Setup <a class="header-anchor" href="#a-firebase-setup" aria-label="Permalink to &quot;A. Firebase Setup&quot;">​</a></h3><ol><li>Go to the <a href="https://console.firebase.google.com/" target="_blank" rel="noreferrer">Firebase Console</a> and create a new project.</li><li>Add a <strong>Web App</strong> to the project to generate the configuration object (copy these values into your <code>.env</code>).</li><li><strong>Authentication:</strong><ul><li>Navigate to <em>Authentication &gt; Sign-in method</em>.</li><li>Enable the <strong>GitHub</strong> provider.</li><li>You will need to provide a Client ID and Client Secret from GitHub (see step B).</li><li>Copy the Firebase <em>Authorization callback URL</em> provided here to use in GitHub.</li></ul></li><li><strong>Firestore Database:</strong><ul><li>Navigate to <em>Firestore Database</em> and click <em>Create database</em>.</li><li>Start in <strong>Production mode</strong>.</li><li><em>Note: You must manually configure Firestore Security Rules before deploying to production to secure the <code>users</code>, <code>sessions</code>, <code>categories</code>, and <code>guilds</code> collections.</em></li></ul></li></ol><h3 id="b-github-oauth-application" tabindex="-1">B. GitHub OAuth Application <a class="header-anchor" href="#b-github-oauth-application" aria-label="Permalink to &quot;B. GitHub OAuth Application&quot;">​</a></h3><ol><li>Go to your GitHub Settings &gt; Developer settings &gt; <strong>OAuth Apps</strong>.</li><li>Click <em>New OAuth App</em>.</li><li>Set the <em>Authorization callback URL</em> to the URL provided by Firebase in step A3.</li><li>Generate a Client Secret.</li><li>Copy the Client ID and Client Secret back into the Firebase Authentication configuration.</li><li><em>Requirement for Daily Sync:</em> Ensure you have a repository named exactly <code>verto-activity</code> on your GitHub account.</li></ol><h3 id="c-spotify-developer-dashboard" tabindex="-1">C. Spotify Developer Dashboard <a class="header-anchor" href="#c-spotify-developer-dashboard" aria-label="Permalink to &quot;C. Spotify Developer Dashboard&quot;">​</a></h3><ol><li>Go to the <a href="https://developer.spotify.com/dashboard" target="_blank" rel="noreferrer">Spotify Developer Dashboard</a> and create a new app.</li><li>Copy the <em>Client ID</em> into your <code>.env</code> file (<code>VITE_SPOTIFY_CLIENT_ID</code>).</li><li>Go to the app&#39;s settings and add the following <strong>Redirect URI</strong> exactly as written: <ul><li><code>http://127.0.0.1:5173/callback</code></li><li><em>(Note: Spotify&#39;s PKCE implementation treats <code>127.0.0.1</code> and <code>localhost</code> as distinct origins. Do not use <code>localhost</code>.)</em></li></ul></li></ol><hr><h2 id="_4-running-locally" tabindex="-1">4. Running Locally <a class="header-anchor" href="#_4-running-locally" aria-label="Permalink to &quot;4. Running Locally&quot;">​</a></h2><p>Once your <code>.env</code> is configured and services are set up:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1. Install dependencies</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2. Start the Vite development server</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Important: Bind to 127.0.0.1 to match the Spotify redirect URI</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --host</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 127.0.0.1</span></span></code></pre></div><p>Access the app at <code>http://127.0.0.1:5173</code>.</p><hr><h2 id="_5-building-deployment" tabindex="-1">5. Building &amp; Deployment <a class="header-anchor" href="#_5-building-deployment" aria-label="Permalink to &quot;5. Building &amp; Deployment&quot;">​</a></h2><p>VERTO is a standard Vite React application and can be deployed to any static hosting service (Vercel, Netlify, Firebase Hosting, GitHub Pages).</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Generate the production build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Preview the production build locally</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> preview</span></span></code></pre></div><h3 id="deployment-notes" tabindex="-1">Deployment Notes: <a class="header-anchor" href="#deployment-notes" aria-label="Permalink to &quot;Deployment Notes:&quot;">​</a></h3><ul><li>Ensure you add your <code>.env</code> variables to your hosting provider&#39;s dashboard.</li><li>Update the <strong>Spotify Redirect URI</strong> in the Spotify Developer Dashboard to match your production domain (e.g., <code>https://verto.yourdomain.com/callback</code>).</li><li>Configure your hosting provider to handle <strong>SPA Routing</strong> (rewrite all traffic to <code>index.html</code>), although VERTO primarily uses state-based routing.</li></ul>`,27)])])}const g=a(n,[["render",o]]);export{u as __pageData,g as default};
